insert into public.sentences (text, text_zh, notebook_id) values ('Sports are commoditized and, alas, prostituted randomness.', '体育运动是商品化的，唉，是被出卖的随机性。', 35);
insert into public.sentences (text, text_zh, notebook_id) values ('When you beat up someone physically, you get exercise and stress relief; when you assault him verbally on the Internet, you just harm yourself.', '当你在身体上打击某人时，你得到锻炼和压力释放；当你在网上言语攻击他时，你只是在伤害自己。', 35);
insert into public.sentences (text, text_zh, notebook_id) values ('Just as smooth surfaces, competitive sports, and specialized work fossilize mind and body, competitive academia fossilizes the soul.', '正如光滑的表面、竞技体育和专业化工作会使身心僵化，竞争性学术会使灵魂僵化。', 35);
insert into public.sentences (text, text_zh, notebook_id) values ('They agree that chess training only improves chess skills but disagree that classroom training (almost) only improves classroom skills.', '他们同意国际象棋训练只能提高象棋技能，但不同意课堂训练（几乎）只能提高课堂技能。', 35);
insert into public.sentences (text, text_zh, notebook_id) values ('Upon arriving at the hotel in Dubai, the businessman had a porter carry his luggage; I later saw him lifting free weights in the gym.', '抵达迪拜酒店后，商人让搬运工搬行李；我后来看到他在健身房举重。', 35);
insert into public.sentences (text, text_zh, notebook_id) values ('Games were created to give nonheroes the illusion of winning. In real life, you don''t know who really won or lost (except too late), but you can tell who is heroic and who is not.', '游戏被创造出来是为了给非英雄胜利的错觉。在现实生活中，你不知道谁真正赢了或输了（除非太晚了），但你能分辨谁是英雄，谁不是。', 35);
insert into public.sentences (text, text_zh, notebook_id) values ('I suspect that IQ, SAT, and school grades are tests designed by nerds so they can get high scores in order to call each other intelligent.', '我怀疑智商、SAT和学校成绩是书呆子设计的测试，这样他们就能得高分，从而互相称对方聪明。', 35);
insert into public.sentences (text, text_zh, notebook_id) values ('They read Gibbon''s Decline and Fall on an eReader but refuse to drink Château LynchBages in a Styrofoam cup.', '他们在电子阅读器上读吉本的《衰亡史》，但拒绝用泡沫塑料杯喝林奇巴热酒庄的酒。', 35);
insert into public.sentences (text, text_zh, notebook_id) values ('My best example of the domain dependence of our minds, from my recent visit to Paris: at lunch in a French restaurant, my friends ate the salmon and threw away the skin; at dinner, at a sushi bar, the very same friends ate the skin and threw away the salmon.', '我们思维领域依赖性的最佳例子，来自我最近的巴黎之行：在法国餐厅吃午餐时，我的朋友们吃三文鱼扔掉鱼皮；在寿司店吃晚餐时，同样的朋友们吃鱼皮扔掉三文鱼。', 35);
insert into public.sentences (text, text_zh, notebook_id) values ('Fragility: we have been progressively separating human courage from warfare, allowing wimps with computer skills to kill people without the slightest risk to their lives.', '脆弱性：我们一直在逐步将人类勇气与战争分离，让有计算机技能的懦夫在没有丝毫生命危险的情况下杀死人。', 35);